#include "descriptions.h"
#include "audio_description.h"

#include "async_log.h"
#include "audiodesc_key.h"    // generated by tools/seal-descriptions
#include "descriptions_key.h" // generated by tools/seal-descriptions

#include <windows.h>

extern "C" IMAGE_DOS_HEADER __ImageBase; // this plugin's own module, which carries the sealed words

namespace D2RAccess {

namespace {
// The texts sealed in the plugin's RCDATA resource `name`; empty, and logged under `tag`, when
// missing or altered.
SealedText::Texts OpenResource(const D2RL::PluginContext* context, const wchar_t* name, const SealedText::Key& key, const char* tag) {
	const auto module = reinterpret_cast<HMODULE>(&__ImageBase);
	const HRSRC info = FindResourceW(module, name, reinterpret_cast<LPCWSTR>(RT_RCDATA));
	const HGLOBAL handle = info ? LoadResource(module, info) : nullptr;
	const auto* bytes = handle ? static_cast<const uint8_t*>(LockResource(handle)) : nullptr;
	if (!bytes) {
		AsyncLog::WarnF(context, "[%s] none: the sealed words are missing from the plugin", tag);
		return {};
	}
	const auto opened = SealedText::Open({bytes, SizeofResource(module, info)}, key);
	if (!opened) {
		AsyncLog::WarnF(context, "[%s] none: the sealed words were altered", tag);
		return {};
	}
	return SealedText::Unpack(*opened);
}
}

SealedText::Texts Descriptions::OpenBundled(const D2RL::PluginContext* context) {
	return OpenResource(context, L"DESCRIPTIONS", Generated::DescriptionsKey, "descriptions");
}

SealedText::Texts AudioDescription::OpenBundled(const D2RL::PluginContext* context) {
	return OpenResource(context, L"AUDIODESC", Generated::AudioDescriptionKey, "audiodesc");
}

}
